import type { SessionConfig } from "../src/utils/session.ts";
import { beforeEach, vi } from "vitest";
import { getSession, updateSession, useSession, readBody } from "../src/index.ts";
import { seal, unseal, defaults as sealDefaults } from "../src/utils/internal/iron-crypto.ts";
import { describeMatrix } from "./_setup.ts";

const PASSWORD_A = "current-password-aaaaaaaaaaaaaaaaaaaa";
const PASSWORD_B = "previous-password-bbbbbbbbbbbbbbbbbbb";
const PASSWORD_C = "older-password-cccccccccccccccccccccc";
const PASSWORD_D = "unknown-password-dddddddddddddddddddd";

const COOKIE = "h3-rot";

const kExtraUnsealPassword = Symbol.for("h3.internal.session.extra-unseal-password");

/** Seal a session payload the way h3 would with `password`. */
function sealWith(password: string, payload: Record<string, unknown>, legacy = false) {
  return seal(
    payload,
    password,
    legacy
      ? {
          ...sealDefaults,
          encryption: { ...sealDefaults.encryption, iterations: 1 },
          integrity: { ...sealDefaults.integrity, iterations: 1 },
        }
      : sealDefaults,
  );
}

/** Read the sealed value of the session cookie from a response, if it was set. */
function setCookieValue(res: Response): string | undefined {
  const cookie = res.headers.getSetCookie().find((c) => c.startsWith(`${COOKIE}=`));
  return cookie && decodeURIComponent(cookie.match(/h3-rot=([^;]+)/)![1]);
}

describeMatrix("session unseal passwords", (t, { it, expect }) => {
  const config: SessionConfig = {
    name: COOKIE,
    password: PASSWORD_A,
    extraUnsealPasswords: [PASSWORD_B],
    generateId: () => "new-id",
  };

  beforeEach(() => {
    t.app.get("/read", async (event) => {
      const session = await getSession(event, config);
      return {
        id: session.id,
        createdAt: session.createdAt,
        data: session.data,
        hasMarker: Reflect.ownKeys(session).includes(kExtraUnsealPassword),
      };
    });
    t.app.post("/write", async (event) => {
      const session = await useSession(event, config);
      await session.update((await readBody(event)) as any);
      return { id: session.id, data: session.data };
    });
    t.app.get("/use", async (event) => {
      const session = await useSession(event, config);
      await session.update({ user: "bob" });
      return { id: session.id, data: session.data };
    });
    t.app.get("/update", async (event) => {
      await updateSession(event, config, { user: "carol" });
      return "ok";
    });
    t.app.get("/validate", async (event) => {
      try {
        await getSession(event, { ...config, extraUnsealPasswords: ["curta"] });
        return { error: null };
      } catch (error) {
        return { error: (error as Error).message };
      }
    });
    t.app.get("/validate-use", async (event) => {
      try {
        await useSession(event, { ...config, extraUnsealPasswords: [PASSWORD_B, "curta"] });
        return { error: null };
      } catch (error) {
        return { error: (error as Error).message };
      }
    });
  });

  const payload = { id: "sess-1", createdAt: Date.now(), data: { user: "alice" } };

  // RF-01
  it("opens a cookie sealed with an extra password, keeping id, createdAt and data", async () => {
    const sealed = await sealWith(PASSWORD_B, payload);
    const res = await t.fetch("/read", { headers: { Cookie: `${COOKIE}=${sealed}` } });
    expect(await res.json()).toMatchObject({
      id: "sess-1",
      createdAt: payload.createdAt,
      data: { user: "alice" },
    });
  });

  // RF-02
  it("writes with password only: the cookie opens with A and not with B", async () => {
    const res = await t.fetch("/update");
    const sealed = setCookieValue(res)!;
    expect(sealed).toBeTruthy();
    expect(await unseal(sealed, PASSWORD_A, sealDefaults)).toMatchObject({
      data: { user: "carol" },
    });
    await expect(unseal(sealed, PASSWORD_B, sealDefaults)).rejects.toThrow("Bad hmac value");
  });

  it("useSession update on a cookie sealed with B writes a cookie that opens only with A", async () => {
    const sealed = await sealWith(PASSWORD_B, payload);
    const res = await t.fetch("/use", { headers: { Cookie: `${COOKIE}=${sealed}` } });
    expect(await res.json()).toMatchObject({ id: "sess-1", data: { user: "bob" } });
    const written = setCookieValue(res)!;
    expect(await unseal(written, PASSWORD_A, sealDefaults)).toMatchObject({
      id: "sess-1",
      data: { user: "bob" },
    });
    await expect(unseal(written, PASSWORD_B, sealDefaults)).rejects.toThrow("Bad hmac value");
  });

  // RF-03
  it("reseals a session opened with an extra password under password on the same request", async () => {
    const sealed = await sealWith(PASSWORD_B, payload);
    const res = await t.fetch("/read", { headers: { Cookie: `${COOKIE}=${sealed}` } });
    const resealed = setCookieValue(res)!;
    expect(resealed).toBeTruthy();
    expect(resealed).not.toBe(sealed);
    expect(await unseal(resealed, PASSWORD_A, sealDefaults)).toMatchObject({
      id: "sess-1",
      createdAt: payload.createdAt,
      data: { user: "alice" },
    });
    await expect(unseal(resealed, PASSWORD_B, sealDefaults)).rejects.toThrow("Bad hmac value");
  });

  it("does not leak the internal marker into the session or the resealed payload", async () => {
    const sealed = await sealWith(PASSWORD_B, payload);
    const res = await t.fetch("/read", { headers: { Cookie: `${COOKIE}=${sealed}` } });
    expect((await res.json()).hasMarker).toBe(false);
    const resealed = setCookieValue(res)!;
    const opened = (await unseal(resealed, PASSWORD_A, sealDefaults)) as Record<string, unknown>;
    expect(Reflect.ownKeys(opened)).not.toContain(kExtraUnsealPassword);
  });

  it("does not renew createdAt when resealing an extra-password session", async () => {
    const createdAt = Date.now() - 30_000;
    const sealed = await sealWith(PASSWORD_B, { ...payload, createdAt });
    const configWithMaxAge = { ...config, maxAge: 3600 };
    t.app.get("/max-age", async (event) => {
      const session = await getSession(event, configWithMaxAge);
      return { createdAt: session.createdAt };
    });
    const res = await t.fetch("/max-age", { headers: { Cookie: `${COOKIE}=${sealed}` } });
    const resealed = setCookieValue(res)!;
    expect(resealed).toBeTruthy();
    expect(await unseal(resealed, PASSWORD_A, sealDefaults)).toMatchObject({ createdAt });
  });

  // RF-04
  it("without extra passwords, a cookie sealed with another password starts a new session", async () => {
    t.app.get("/plain", async (event) => {
      const session = await getSession(event, { name: COOKIE, password: PASSWORD_A, generateId: () => "new-id" });
      return { id: session.id };
    });
    const sealed = await sealWith(PASSWORD_B, payload);
    const res = await t.fetch("/plain", { headers: { Cookie: `${COOKIE}=${sealed}` } });
    expect(await res.json()).toEqual({ id: "new-id" });
  });

  it("without extra passwords, a legacy cookie sealed with password still opens and is resealed", async () => {
    t.app.get("/plain", async (event) => {
      const session = await getSession(event, { name: COOKIE, password: PASSWORD_A, generateId: () => "new-id" });
      return { id: session.id };
    });
    const sealed = await sealWith(PASSWORD_A, payload, true);
    const res = await t.fetch("/plain", { headers: { Cookie: `${COOKIE}=${sealed}` } });
    expect(await res.json()).toEqual({ id: "sess-1" });
    expect(setCookieValue(res)).toBeTruthy();
  });

  // D-05
  it("with legacySealFallback: false, a legacy cookie sealed with an extra password is rejected", async () => {
    t.app.get("/strict", async (event) => {
      const session = await getSession(event, {
        ...config,
        legacySealFallback: false,
      });
      return { id: session.id };
    });
    const sealed = await sealWith(PASSWORD_B, payload, true);
    const res = await t.fetch("/strict", { headers: { Cookie: `${COOKIE}=${sealed}` } });
    expect(await res.json()).toEqual({ id: "new-id" });
    expect(setCookieValue(res)).toBeUndefined();
  });

  // Session header is never resealed
  it("does not reseal a session opened with an extra password from the session header", async () => {
    const sealed = await sealWith(PASSWORD_B, payload);
    const res = await t.fetch("/read", { headers: { "x-h3-rot-session": sealed } });
    expect(await res.json()).toMatchObject({ id: "sess-1", data: { user: "alice" } });
    expect(res.headers.getSetCookie()).toHaveLength(0);
  });

  // RF-05
  it("discards a session sealed with an extra password whose maxAge has expired", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      t.app.get("/max-age", async (event) => {
        const session = await getSession(event, { ...config, maxAge: 60 });
        return { id: session.id, data: session.data };
      });
      const sealed = await sealWith(PASSWORD_B, { ...payload, createdAt: t0 - 120_000 });
      const res = await t.fetch("/max-age", { headers: { Cookie: `${COOKIE}=${sealed}` } });
      const body = await res.json();
      expect(body.id).toBe("new-id");
      expect(body.data).toEqual({});
    } finally {
      vi.useRealTimers();
    }
  });

  it("discards a session sealed with an extra password whose idleTimeout has expired", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      t.app.get("/idle", async (event) => {
        const session = await getSession(event, { ...config, idleTimeout: 60 });
        return { id: session.id, data: session.data };
      });
      const sealed = await sealWith(PASSWORD_B, {
        ...payload,
        createdAt: t0 - 600_000,
        lastSeenAt: t0 - 120_000,
      });
      const res = await t.fetch("/idle", { headers: { Cookie: `${COOKIE}=${sealed}` } });
      const body = await res.json();
      expect(body.id).toBe("new-id");
      expect(body.data).toEqual({});
    } finally {
      vi.useRealTimers();
    }
  });

  // Cost of derivations: 1 + N attempts per invalid cookie in strict mode
  it("an invalid cookie costs one derivation attempt per configured password", async () => {
    t.app.get("/cost", async (event) => {
      const session = await getSession(event, {
        ...config,
        extraUnsealPasswords: [PASSWORD_B, PASSWORD_C],
        legacySealFallback: false,
      });
      return { id: session.id };
    });
    t.app.get("/cost-single", async (event) => {
      const session = await getSession(event, {
        ...config,
        extraUnsealPasswords: [],
        legacySealFallback: false,
      });
      return { id: session.id };
    });
    const sealed = await sealWith(PASSWORD_D, payload);
    const headers = { Cookie: `${COOKIE}=${sealed}` };

    const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
    try {
      deriveBits.mockClear();
      await t.fetch("/cost-single", { headers });
      const single = deriveBits.mock.calls.length;
      expect(single).toBeGreaterThan(0);

      deriveBits.mockClear();
      await t.fetch("/cost", { headers });
      expect(deriveBits.mock.calls.length).toBe(3 * single);
    } finally {
      deriveBits.mockRestore();
    }
  });

  // RF-06
  it("rejects an extra password shorter than the minimum, naming its index, even without a cookie", async () => {
    const res = await t.fetch("/validate");
    const { error } = await res.json();
    expect(error).toContain("extraUnsealPasswords[0]");
  });

  it("does not echo the invalid extra password in the error", async () => {
    const res = await t.fetch("/validate-use");
    const { error } = await res.json();
    expect(error).toContain("extraUnsealPasswords[1]");
    expect(error).not.toContain("curta");
  });

  it("validates extra passwords on useSession too", async () => {
    const res = await t.fetch("/validate-use");
    expect((await res.json()).error).not.toBeNull();
  });
});

