    const { error } = await res.json();
    expect(error).toContain("extraUnsealPasswords[1]");
    expect(error).not.toContain("curta");
  });

  it("validates extra passwords on useSession too", async () => {
    const res = await t.fetch("/validate-use");
    expect((await res.json()).error).not.toBeNull();
  });
});

