/**
 * Throws if an extra unseal password is not a string of at least the seal's
 * minimum length. The error names the index, never the value.
 */
export function assertExtraUnsealPasswords(config: SessionConfig): void {
  const passwords = config.extraUnsealPasswords || [];
  const { encryption, integrity } = { ...sealDefaults, ...config.seal };
  const min = Math.max(encryption.minPasswordlength, integrity.minPasswordlength);
  for (const [index, password] of passwords.entries()) {
    if (typeof password !== "string" || password.length < min) {
      throw new Error(
        `Invalid extraUnsealPasswords[${index}]: must be a string of at least ${min} characters`,
      );
    }
  }
}

